class SfxSynth:
    """Procedurally synthesises the game's soft sci-fi interface sounds (clicks, hovers, selects, tower place /
upgrade / sell and the "denied" buzz) as 16-bit PCM mono WAV files. Everything is generated from sine / triangle
oscillators with pitch sweeps, gentle FM, short attack and exponential decay envelopes, a one-pole low-pass for
softness and an optional light bit-crush; there is no noise. The output is original and therefore CC0.

Usage: java -cp build lindefense.tools.SfxSynth assets/sfx"""
    class Buf:
        """Growable mono float buffer with mixing helpers."""
        def __init__(self):
            self.d = ([0.0] * 0)
            pass
        def ensure(self, n):
            if len(self.d) < n:
                self.d = _j.copy_of(self.d, n, 0.0)
        def voice(self, at, dur, f0, f1, tri, fm, ratio, amp, attack, decay):
            """Adds one enveloped voice.
@param at      start time in seconds
@param dur     length in seconds
@param f0,f1   start / end frequency in Hz (exponential sweep)
@param tri     0 = pure sine, 1 = pure triangle
@param fm      FM index (decays with the note)
@param ratio   FM modulator frequency ratio
@param amp     peak amplitude
@param attack  attack time in seconds
@param decay   decay time constant in seconds"""
            start = _j.to_int((at * SfxSynth.RATE))
            n = _j.to_int((dur * SfxSynth.RATE))
            self.ensure((start + n))
            phase = 0.0
            mphase = 0.0
            for i in range(n):
                t = (i / float(SfxSynth.RATE))
                u = (i / float(max(1, (n - 1))))
                f = (f0 * math.pow((f1 / f0), u))
                phase += (((2 * math.pi) * f) / SfxSynth.RATE)
                mphase += ((((2 * math.pi) * f) * ratio) / SfxSynth.RATE)
                env = ((_j.dmin(1, (t / attack)) * math.exp(((-t) / decay))) * _j.dmin(1, ((dur - t) / 0.006)))
                p = (phase + ((fm * math.exp(((-t) / (decay * 1.5)))) * math.sin(mphase)))
                sine = math.sin(p)
                triangle = ((2 / math.pi) * math.asin(math.sin(p)))
                self.d[(start + i)] += ((((sine * (1 - tri)) + (triangle * tri)) * env) * amp)
        def echo(self, delay, feedback, taps):
            """Soft feedback echo that gives the sounds a little glassy space."""
            dl = _j.to_int((delay * SfxSynth.RATE))
            self.ensure((len(self.d) + (dl * taps)))
            for i in range(dl, len(self.d)):
                self.d[i] += (self.d[(i - dl)] * feedback)
        def lowpass(self, cutoff):
            a = (1 - math.exp(((((-2) * math.pi) * cutoff) / SfxSynth.RATE)))
            y = 0.0
            for i in range(len(self.d)):
                y += (a * (self.d[i] - y))
                self.d[i] = y
        def crush(self, bits, hold):
            """Light digital grit: sample-and-hold by hold samples at bits resolution."""
            q = math.pow(2, (bits - 1))
            held = 0.0
            for i in range(len(self.d)):
                if _j.imod(i, hold) == 0:
                    held = (_j.jround((self.d[i] * q)) / q)
                self.d[i] = held
        def finish(self, peak):
            """Normalises to the given peak and adds a short fade-out."""
            max_ = 1e-6
            for v in self.d:
                max_ = _j.dmax(max_, abs(v))
            fade = _j.to_int((0.01 * SfxSynth.RATE))
            for i in range(len(self.d)):
                g = (peak / max_)
                if i > (len(self.d) - fade):
                    g *= ((len(self.d) - i) / float(fade))
                self.d[i] *= g
